import { lstat, rm, unlink } from 'node:fs/promises';
import path from 'node:path';
import os from 'node:os';
import { z } from 'zod';
import { globalSkillsRoot, setGlobalSkillEnabled } from './carb-global-skills.js';

const params = { provider: z.string().min(1).max(80), projectPath: z.string().min(1).max(4096).optional(), skillId: z.string().min(1).max(4096) };
export const managedSkillMethods = {
  'skills.setManagedEnabled': { params: z.object({ ...params, enabled: z.boolean() }), result: z.object({ enabled: z.boolean() }) },
  'skills.deleteManaged': { params: z.object(params), result: z.object({}) },
};
const normalized = value => process.platform === 'win32' ? path.resolve(value).toLowerCase() : path.resolve(value);
async function findSkill(orchestrator, p) {
  const inventory = await orchestrator.listSkills(p.provider, p.projectPath);
  const matches = inventory.skills.filter(skill => skill.id === p.skillId);
  if (matches.length !== 1) throw new Error('技能已不存在或无法唯一识别，请刷新列表。');
  return matches[0];
}
function globalName(skill) {
  if (skill.source?.type !== 'folder' || typeof skill.source.path !== 'string') return undefined;
  const folder = path.resolve(skill.source.path), root = path.resolve(globalSkillsRoot());
  return normalized(path.dirname(folder)) === normalized(root) ? path.basename(folder) : undefined;
}
export async function setManagedSkillEnabled(orchestrator, p) {
  const skill = await findSkill(orchestrator, p);
  const name = globalName(skill);
  if (name) return { enabled: setGlobalSkillEnabled(name, p.enabled) };
  return { enabled: await orchestrator.setSkillEnabled(p.provider, p.projectPath, p.skillId, p.enabled) };
}
export async function deleteManagedSkill(orchestrator, p) {
  const skill = await findSkill(orchestrator, p);
  if (skill.source?.type !== 'folder' || typeof skill.source.path !== 'string' || !path.isAbsolute(skill.source.path)) throw new Error('此技能没有可删除的本地目录。');
  const folder = path.resolve(skill.source.path);
  const protectedPaths = [path.parse(folder).root, os.homedir(), p.projectPath, globalSkillsRoot()].filter(Boolean).map(normalized);
  if (protectedPaths.includes(normalized(folder))) throw new Error('无法删除此受保护的目录。');
  const before = await lstat(folder, { bigint: true });
  if (!before.isDirectory() && !before.isSymbolicLink()) throw new Error('技能目录已发生变化，请刷新列表。');
  const marker = await lstat(path.join(folder, 'SKILL.md'));
  if (!marker.isFile()) throw new Error('技能文件已发生变化，请刷新列表。');
  const after = await lstat(folder, { bigint: true });
  if (before.dev !== after.dev || before.ino !== after.ino || before.birthtimeNs !== after.birthtimeNs || before.isSymbolicLink() !== after.isSymbolicLink()) throw new Error('技能目录已发生变化，请重试。');
  if (before.isSymbolicLink()) await unlink(folder);
  else await rm(folder, { recursive: true, force: false });
  return {};
}
